return ['x-generator'=>'GlotPress/4.0.3','translation-revision-date'=>'2025-11-12 18:00:15+0000','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - FiboSearch &#8211; Ajax Search for WooCommerce - Stable (latest release)','language'=>'pl','messages'=>['Open search bar'=>'Otwórz pasek wyszukiwania','As an Elementor widget named “FiboSearch”'=>'Jako widżet Elementora o nazwie „FiboSearch”','Minimum theme versions'=>'Minimalne wersje motywu','Minimum theme version'=>'Minimalna wersja motywu','The integrations will not be activated unless the plugins are updated to the minimum required versions.'=>'Integracje nie zostaną włączone, dopóki wtyczki nie zostaną zaktualizowane do minimalnej wymaganej wersji.','%1$s, current version: %2$s, minimum version: %3$s'=>'%1$s, bieżąca wersja: %2$s, minimalna wersja: %3$s','We have detected that you are using plugins that we integrate with, but in versions that we do not support:'=>'Wykryliśmy, że korzystasz z wtyczek, z którymi się integrujemy, ale w wersjach, których nie obsługujemy:','Unsupported plugin versions'=>'Nieobsługiwane wersje wtyczek','We’ve detected that you’re using the %1$s theme, which we support, but your current version (%2$s) is not compatible with our integration. To activate and use our integration properly, please update the theme to at least version %3$s.'=>'Wykryliśmy, że używasz motywu %1$s, który obsługujemy, ale Twoja obecna wersja (%2$s) nie jest zgodna z naszą integracją. Aby włączyć i prawidłowo korzystać z naszej integracji, zaktualizuj motyw co najmniej do wersji %3$s.','Unsupported theme version'=>'Nieobsługiwana wersja motywu','Go to <a href="%s">Appearance -> Menus</a> to configure the FiboSearch bar.'=>'Przejdź do <a href="%s">Wygląd -> Menu</a>, aby skonfigurować pasek FiboSearch.','Close'=>'Zamknij','Searching in variable products GUID is available only in <a target="_blank" href="%s">the pro version</a>.'=>'Wyszukiwanie w produktach o zmiennym GUID jest dostępne tylko w <a target="_blank" href="%s">wersji Pro</a>.','searching also in variable products GUID'=>'wyszukiwanie również w produktach o zmiennym GUID','Make your products searchable by their Global Unique Identifier (GTIN, UPC, EAN or ISBN).'=>'Udostępnij możliwość wyszukiwania swoich produktów według globalnego unikatowego identyfikatora (GTIN, UPC, EAN lub ISBN).','Search in GUID'=>'Wyszukaj w GUID','User search history'=>'Historia wyszukiwania użytkownika','Open search in the mobile overlay'=>'Otwórz wyszukiwanie w nakładce mobilnej','You use the %s plugin, which may cause errors in the search results returned by our plugin.'=>'Używasz wtyczki %s, co może powodować błędy w wynikach wyszukiwania zwracanych przez naszą wtyczkę.','Pirx (compact) is proper name.Pirx (compact version)'=>'Pirx (wersja kompaktowa)','Go to <code>WooCommerce -> Settings -> <a href="%s" target="_blank">Products Filter (tab)</a> -> Advanced (tab) -> Options (tab)</code> -> scroll to the bottom to <code>Forcing disabling of functionality</code> option -> enter the value <code>by_text</code> and save changes.'=>'Przejdź do <code>WooCommerce -> Ustawienia -> <a href="%s" target="_blank">Filtr produktów (karta)</a> -> Zaawansowane (karta) -> Opcje (karta)</code> -> przewiń na dół do opcji <code>Wymuszanie wyłączenia funkcjonalności</code> -> wprowadź wartość <code>by_text</code> i zapisz zmiany.','Incompatible "HUSKY - Advanced searching by Text" extension from "HUSKY - Products Filter Professional for WooCommerce" is active'=>'Niezgodne rozszerzenie „HUSKY - Zaawansowane wyszukiwanie według tekstu” z rozszerzenia „HUSKY - Filtr produktów Professional dla WooCommerce” jest włączone','You have defined %s constant and it\'s set to <code>true</code>. It means only critical searches will be stored in the database. Other modules than Critical Searches are not visible in this mode.'=>'Zdefiniowano stałą %s i ustawiono ją na <code>true</code>. Oznacza to, że w bazie danych będą przechowywane tylko krytyczne wyszukiwania. Moduły inne niż Krytyczne Wyszukiwania nie są widoczne w tym trybie.','Warning:'=>'Ostrzeżenie:','Search bar underlay'=>'Podkładka paska wyszukiwania','This phrase returns some results.'=>'Ta fraza zwraca pewne wyniki.','No interaction! This is only a preview.'=>'Brak interakcji! To tylko podgląd.','(Flatsome settings) Go to <code>Appearance -> <a href="%s" target="_blank">Customize</a> -> Header -> Cart</code> and change <code>Cart Style</code> option to <code>Dropdown</code> or <code>Link only</code>.'=>'(Ustawienia Flatsome) Przejdź na stronę <code>Wygląd -> <a href="%s" target="_blank">Dostosuj</a> -> Header -> Cart</code> i zmień opcję <code>Cart Style</code> na <code>Dropdown</code> lub <code>Link only</code>.','(Flatsome settings) Go to <code>Appearance -> <a href="%s" target="_blank">Customize</a> -> Header -> Search</code> and change <code>Search Icon Type</code> option to <code>Dropdown</code>.'=>'(Ustawienia Flatsome) Przejdź na stronę <code>Wygląd -> <a href="%s" target="_blank">Dostosuj</a> -> Header -> Search</code> i zmień opcję <code>Search Icon Type</code> na <code>Dropdown</code>.','(FiboSearch settings) Go to <code>Autocomplete</code> tab and disable <code>Show Details Panel</code> option.'=>'(Ustawienia FiboSearch) Przejdź do zakładki <code>Autouzupełnienie</code> i wyłącz opcję <code>Pokaż panel ze szczegółami</code>.','Solutions (you only need to use one of them)'=>'Rozwiązania (wystarczy, że skorzystasz z jednej z nich)','There is a rare combination of <b>FiboSearch</b> and <b>Flatsome</b> settings that might cause issues when adding a product to the cart from the autocomplete search results. Unfortunately, you have this combination. You can\'t use <b>Off-Canvas Sidebar</b> as <b>Cart Style (Flatsome)</b>, <b>Search Icon Type</b> as <b>Search Icon Type (Flatsome)</b>, and <b>Details Panel (FiboSearch)</b> at the same time. The solution is to resign from one of these options.'=>'Istnieje bardzo rzadka kombinacja ustawień <b>FiboSearch</b> oraz <b>Flatsome</b>  która może powodować błąd wyglądu strony podczas dodawania produktu do koszyka z poziomu wyszukiwarki. Niestety wykryliśmy, że masz taką kombinację. Nie możesz używać <b>Off-Canvas Sidebar</b> jako <b>Cart Style (Flatsome)</b>, <b>Search Icon Type</b> jako <b>Search Icon Type (Flatsome)</b> oraz <b>Panel ze szczegółami (FiboSearch)</b> w tym samym czasie. Aby rozwiązać ten konflikt, wystarczy zmienić jedną z powyższych opcji.','There is a conflict between Flatsome theme settings and our plugin'=>'Wykryto konflikt motywu Flatsome z wtyczką FiboSearch','See an example of a more complex "No results" message in <a href="%s" target="_blank">our documentation</a>.'=>'Zobacz bardziej rozbudowane przykłady wiadomości "Brak wyników"  <a href="%s" target="_blank">w naszej dokumentacji</a>.','The following HTML tags are allowed:<br /> %s.'=>'Tagi HTML, które są dozwolone:<br /> %s.','Export CSV'=>'Eksportuj CSV','The current search history is presented when the user clicked/taped on the search bar, but hasn\'t yet typed the query. The history includes the last searched products and phrases.'=>'Historia wyszukiwania użytkownika wyświetlana jest po kliknięciu w wyszukiwarkę, ale jeszcze przed rozpoczęciem pisania. Historia zawiera ostatnio wyszukiwane produkty oraz frazy.','Extra views'=>'Dodatkowe widoki','Solaris is proper name.Solaris'=>'Solaris','Clear'=>'Wyczyść','Your search history'=>'Twoja historia wyszukiwania','Analytics tab'=>'Analityka','Go to FiboSearch Settings page → %s to see more.'=>'Przejdź do strony ustawień FiboSearch → %s, aby zobaczyć więcej.','FiboSearch - Search Analytics'=>'FiboSearch - analityka wyszukiwań','Show widget with critical searches in Dashboard'=>'Pokaż widget z krytycznymi frazami w kokpicie','Search analytics system helps to eliminate search phrases that don’t return any results. Also, allows to explore trending keywords. <a target="_blank" href="%s">Find our more</a> how to use and customize FiboSearch Analytics.'=>'Analityka wyszukiwań pozwala na wyeliminowanie fraz wyszukiwawczych, które nie wskazują na żaden produkt. Można również przeglądać popularne słowa kluczowe. <a target="_blank" href="%s">Dowiedź się</a> jak używać i skonfigurować analitykę FiboSearch.','Analytics'=>'Analityka','As a block'=>'Dodaj blok','learn how to use blocks'=>'dowiedz się jak używać bloków','Not regenerated images'=>'Nieodnowione miniaturki zdjęć produktów','If you have regenerated the images or do not think it is necessary, you can ignore and dismiss this message: %s'=>'Jeżeli miniaturki ostały już odnowione lub uważasz, że nie ma takiej potrzeby, możesz zignorować i zamknąć to powiadomienie: %s','It is recommended to generate a special small image size for existing products to ensure a better user experience. This is a one-time action.'=>'Rekomenduje się wygenerowanie specjalnych miniaturek zdjęć dla istniejących produktów w celu zapewnienia lepszego UX. To jest jednorazowa akcja.','Regenerate images'=>'Odnowienie miniaturek','Pirx is proper name.Pirx'=>'Pirx','Are you sure you want to reset stats?'=>'Czy na pewno chcesz zresetować statystyki?','Incompatible "Searching by Text" extension from "WOOF - WooCommerce Products Filter plugin" is active'=>'Niekompatybilny dodatek "Searching by Text" należący do wtyczki "WOOF - WooCommerce Products Filter" jest aktywny','Maintenance'=>'Konserwacja','reset your stats'=>'zresetować statystyki','The FiboSearch analyzer found <b>1 critical search phrase</b>.'=>'Skrypt FiboSearch do analityki znalazł <b>jedną krytyczną frazę</b>.' . "\0" . 'Skrypt FiboSearch do analityki znalazł <b>%d krytyczne frazy</b>.' . "\0" . 'Skrypt FiboSearch do analityki znalazł <b>%d krytycznych fraz</b>.','These phrases don`t return any search results. It\'s time to fix it.'=>'Gdy użytkownicy wpisują te frazy w wyszukiwarkę, nie wyświetlają się żadne wyniki wyszukiwania. Pora to naprawić.','These phrases have been typed by users over the last 1 day.'=>'Te frazy zostały wpisane przez użytkowników w przeciągu ostatniego dnia.' . "\0" . 'Te frazy zostały wpisane przez użytkowników w przeciągu %d dni.' . "\0" . 'Te frazy zostały wpisane przez użytkowników w przeciągu %d dni.','block titleFiboSearch'=>'FiboSearch','block keywordproduct'=>'produkt','block keywordsearch'=>'wyszukiwarka','block descriptionAJAX (live) search form for WooCommerce'=>'Wyszukiwarka do WooCommerce z autouzupełnianiem','block titleFiboSearch navigation item'=>'Element nawigacji FiboSearch','<a target="_blank" href="%s">Read more</a> about this feature.'=>'<a target="_blank" href="%s">Dowiedz się więcej</a> o tej funkcjonalności.','Appearance'=>'Wygląd','Background color'=>'Kolor tła','Breakpoint'=>'Breakpoint','Covers anything that is displayed on the screen and simplifies the view to search bar + results.'=>'Przykrywa wszystko co jest wyświetlone na ekranie, pozwalając skupić się użytkownikowi tylko na widoku paska wyszukiwania oraz wyników.','Debug page'=>'Strona debugowania','FiboSearch might be displayed as a search bar, icon, or mixed of them.'=>'FiboSearch może być wyświetlone jako pole wyszukiwania, ikonka lub to i to.','FiboSearch provides two different styles of search bars: Solaris and Pirx. Solaris has a rectangular shape while Pirx is a bean-shaped bar with curvy and smooth edges. <a target="_blank" href="%s">See the differences</a> between Solaris and Pirx style.'=>'FiboSearch posiada dwa różne style dla pola wyszukiwania: Solaris i Pirx. Solaris ma ostre krawędzie podczas gdy Pirx jest owalny, w kształcie fasoli. <a target="_blank" href="%s">Zobacz różnice</a> między stylem Solaris a stylem Pirx.','Go to <code>WooCommerce -> Settings -> <a href="%s" target="_blank">Products Filter (tab)</a> -> Extensions (tab)</code>, uncheck <code>HUSKY - Advanced searching by Text</code> extension and save changes.'=>'Przejdź do <code>WooCommerce -> Ustawienia -> <a href="%s" target="_blank">karta Products Filter</a> -> karta Extensions</code>, wyłącz dodatek <code>HUSKY - Advanced searching by Text</code> i zapisz ustawienia.','Go to <code>WooCommerce -> Settings -> <a href="%s" target="_blank">Products Filter (tab)</a> -> Options (tab)</code>, set <code>Try to ajaxify the shop</code> option to <code>No</code> and save changes.'=>'Przejdź do <code>WooCommerce -> Ustawienia -> <a href="%s" target="_blank">karta Products Filter</a> -> karta Options</code>, ustaw opcję <code>Try to ajaxify the shop</code> na <code>No</code> i zapisz zmiany.','Here is the list of phrases that were typed by users who followed the pattern: type the phrase into the bar → clicked “See all results” or just hit enter/return (for Mac users)'=>'Tutaj jest lista fraz, które wpisali użytkownicy w taki sposób: wpisali coś w polu wyszukiwania → kliknęli "Zobacz wszystkie wyniki" lub po prostu nacisnęli enter, lub return (dla użytkowników Mac).','Icon on desktop, search bar on mobile'=>'Ikonka (desktop), pole wyszukiwania (mobilki)','Incompatible "HUSKY - Advanced searching by Text" extension in WOOF - WooCommerce Products Filter'=>'Niekompatybilny dodatek "HUSKY - Advanced searching by Text" należący do wtyczki WOOF - WooCommerce Products Filter','Incompatible "Try to ajaxify the shop" option from WOOF - WooCommerce Products Filter plugin is enabled'=>'Niekompatybilna opcja "Try to ajaxify the shop" należąca do wtyczki WOOF - WooCommerce Products Filter jest włączona','Incompatible "Try to ajaxify the shop" option in WOOF - WooCommerce Products Filter'=>'Niekompatybilna opcja "Try to ajaxify the shop" należąca do wtyczki WOOF - WooCommerce Products Filter','Label'=>'Etykieta','Make your custom fields searchable from our search bar.'=>'Pozwól na wyszukiwanie we własnych polach','On desktop'=>'Na komputerze stacjonarnym','On mobile'=>'Na urządzeniach mobilnych','Other colors'=>'Inne kolory','Poor!'=>'Słabo!','See what each of these layouts looks like'=>'Zobacz jak wygląda każdy z tych układów','The list of phrases with results is displayed to users as a drop down list with auto suggestions.'=>'Tutaj jest lista fraz, które zwracają wyniki. Wyniki te są wyświetlane użytkownikom jako automatyczne podpowiedzi (autouzupełnianie).','The synonyms feature allows your users to find more relevant results. If your products have alternative names and users often misspell them, consider adding synonyms. <a target="_blank" href="%s">Read more</a> about this feature.'=>'Synonimy pozwalają użytkownikom znaleźć produkty w szybszy i łatwiejszy sposób. Jeżeli twoje produkty zawierają różne warianty nazw, a użytkownicy często się mylą, rozważ dodanie tych nazw jako synonimów. <a target="_blank" href="%s">Dowiedz się więcej</a> o tej funkcjonalności.','Top searches - autocomplete'=>'Najpopularniejsze wyszukiwania - autouzupełnianie','Top searches - WooCommerce search results page'=>'Najpopularniejsze wyszukiwania - strona z wynikami wyszukiwania WooCommerce','You have selected the <b>Appearance -> Style -> Pirx</b> option. Pirx style forces a submit button to be enabled. You can find this option a few rows below. That\'s why this option is blocked.'=>'Wybrałeś opcję <b>Wygląd -> Styl -> Pirx</b>. Wybranie stylu Pirx wymaga włączenia przycisku "Submit". Możesz znaleźć tę opcję kilka linii niżej. To dlatego ta opcja jest wyłączona.','%s is enabled but not effective. It is missing core files. Please reinstall the plugin.'=>'Wtyczka %s jest włączona, ale nie działa. Brakuje ważnych plików źródłowych. Zainstaluj wtyczkę jeszcze raz. ','Install the latest version of WordPress for our plugin for optimal performance!'=>'Zainstaluj najnowszą wersję WordPressa dla optymalnego działania FiboSearch!','Replace them'=>'Podmień pola wyszukiwania','Replace your theme\'s default search bars.'=>'Podmień domyślne wyszukiwarki w twoim motywie','Search bars'=>'Pola wyszukiwania','0 searches with results'=>'0 wyszukiwań z wynikami','<b>Adding the phrase to the product name</b> - just add the phrase to the product name, description, SKU, custom field, tag or anything else that\'s in your current search scope'=>'<b>Dodanie nowych słów do nazwy produktu</b> - po prostu dodaj tę frazę do nazwy produktu, opisu, SKU, jako własne pola, tagi lub cokolwiek innego, co jest w zakresie wyszukiwania.','<b>Synonyms</b> - if the phrase is an alternate version of any other words, add it as a synonym. Learn more about <a href="%s" target="_blank">the synonyms feature.'=>'<b>Synonimy</b> - jeżeli fraza posiada alternatywne wersje, dodaj je jako synonimy. <a target="_blank" href="%s">Dowiedz się więcej</a> o tym, jak działają synonimy w FiboSearch.','<b>Varied naming convention</b> - this issue occurs when users may type a phrase in several different way – eg. you have SKU "CB-978-8-7290", but users might type it in a different way: "CB978 8 7290", "CB/978/8/7290", "CB97887290" and so on. To solve such problems, contact our <a href="%s" target="_blank">technical support</a>, because the solution may be different for each case.'=>'<b>Zróżnicowanie nazewnictwa</b> - ten problem pojawia się, gdy fraza może mieć wiele bardzo podobnych wersji np. gdy mamy kod SKU "CB-978-8-7290", ale użytkownicy wpisują go na różne sposoby: "CB978 8 7290", "CB/978/8/7290", "CB97887290" itp. W celu rozwiązania tego problemu skontaktuj się z naszym <a href="%s" target="_blank">wsparciem technicznym</a>, ponieważ każdy przypadek może być inny i musimy analizować je indywidualnie. ','autocomplete'=>'autouzupełnienie','Can\'t check the status. The search index hasn\'t been completed. Go to the Indexer tab and wait until the search index is completed.'=>'Nie można sprawdzić statusu. Indeks wyszukiwawczy nie został jeszcze zbudowany. Przejdź do karty "Indeks" i czekaj, aż indeks zbuduje się do końca.','Check'=>'Sprawdź','Check if it\'s been solved'=>'Sprawdź, czy fraza jest naprawiona','Check the indexer status'=>'Sprawdź status indeksera','Click the button below to remove this phrase from the list.'=>'Kliknij przycisk poniżej, aby usunąć tę frazę z listy.','Critical searches without result'=>'Frazy krytyczne, które nie zwracają żadnych wyników','Enable search analytics'=>'Włącz analitykę wyszukiwania','Fantastic! The FiboSearch analyzer hasn\'t found any critical search phrases for the last %d days.'=>'Fantastycznie! Skrypt do analityki FiboSearch nie znalazł żadnych krytycznych fraz w przeciągu ostatnich %d dni.','How to fix it?'=>'Jak to naprawić?','It\'s sorted.'=>'Rozwiązane.','Language'=>'Język','load another %d phrase'=>'załaduj ostatnią frazę' . "\0" . 'załaduj kolejne %d frazy' . "\0" . 'załaduj kolejne %d fraz','Mark this phrase as resolved'=>'Oznacz tę frazę jako rozwiązaną.','Perfect!'=>'Świetnie!','Phrase'=>'Fraza','Recheck the status'=>'Sprawdź status jeszcze raz','Repetitions'=>'Powtórzeń','returning results'=>' z wynikami','Returns suggestions based on likely relevance, even though a search keyword may not exactly match. E.g if you type “ipho<b>m</b>e” you get the same results as for “iphone”. <a target="_blank" href="%s">Read more</a> about the fuzzy search feature.'=>'Zwraca wyniki na podstawie zbliżonej trafności, nawet jeśli słowo kluczowe nie do końca pasuje do produktu. Np. jeżeli użytkownik napisze “ipho<b>m</b>e” to zobaczy te same wyniki, tak jakby wpisał poprawnie “iphone”. <a target="_blank" href="%s">Czytaj więcej</a> o dopasowaniu rozmytym.','Search Analytics'=>'Analityka wyszukiwania','search results page'=>'strona z wynikami wyszukiwania','Searches'=>'Wyszukiwania','Searches stats (last %d days)'=>'Statystyka wyszukiwań (ostatnie %d dni)','show top 100 phrases'=>'zobacz 100 najpopularniejszych fraz','Shows stats only for the selected language.'=>'Pokaż statystyki tylko dla wybranego języka','Something went wrong'=>'Coś poszło nie tak','Still this phrase doesn\'t return any results. Learn how to fix it.'=>'Ta fraza wciąż nie zwraca żadnych wyników. Spróbuj to naprawić.','There are several ways to solve these problems. Every phrase may require a different approach. See what methods you could use:'=>'Istnieje kilka sposobów na rozwiązanie tych problemów. Każda fraza może wymagać innego podejścia, aby ją naprawić. Zobacz, co można zrobić:','This phrase has been resolved! This row will disappear after refreshing the page.'=>'Ta fraza została rozwiązana! Ten wiersz zniknie po odświeżeniu strony.','Total searches'=>'Wszystkich wyszukiwań','Darkened background'=>'Przyciemniane tło','Darkening the page background while autocomplete is active gives it stronger emphasis, minimizing elements (e.g., ads, carousels, and other page content) that could distract users from considering autocomplete suggestions.'=>'Przyciemnianie tła strony podczas wyszukiwania pozwala zminimalizować rozproszenie użytkownika.','Furthermore, you can override this option for a specific search bar via shortcode params. <a href="%s" target="_blank">Learn more about shortcodes parameters</a>.'=>'Dodatkowo możesz nadpisać tę opcję dla konkretnego pola wyszukiwania, używając shortcode\'a. <a href="%s" target="_blank">Dowiedz się więcej o parametrach shortcode\'a</a>.','This option is <b>overridden</b> by the seamless integration with the %s theme. If you want to change the value of this option, disable the integration in <br /><b>WooCommerce -> FiboSearch -> Starting (tab)</b>.'=>'Ta opcja jest <b>nadpisana</b> przez integrację z motywem %s. Jeśli chcesz zmienić wartość tej opcji, wyłącz integrację w <br /><b>WooCommerce -> FiboSearch -> karta Jak zacząć?</b>.','Dismiss'=>'Ukryj','Elementor search results template'=>'Templatka wyników wyszukiwania w Elementorze','If you think the search results page is displaying your products correctly, you can ignore and dismiss this message: %s'=>'Jeżeli uważasz, że strona z wynikami wyszukiwania wyświetla się prawidłowo, możesz zignorować i wyłączyć tę wiadomość: %s','There is no correct template in the Elementor Theme Builder for the WooCommerce search results page.'=>'Nie masz poprawnej templatki Elementora dla stron wyników wyszukiwania WooCommerce.','You are using Elementor and we noticed that the template used in the search results page titled <strong>%s</strong> does not include the <strong>Archive Products</strong> widget.'=>'Używasz Elementora i zauważyliśmy, że templatka, której używasz do wyświetlania strony z wynikami wyszukiwania <strong>%s</strong> nie posiada widgetu <strong>Archive Products</strong>.','Exclude'=>'Nie indeksuj produktów spełniających poniższe reguły','Exclude the product group from the search results or allow search only among the indicated product group.'=>'Wyklucz grupę produktów z wyników wyszukiwania lub pozwól wyszukiwać tylko wśród wskazanych grup.','Exclude/include products'=>'Indeksuj/Nie indeksuj produkty','FiboSearch Team'=>'Zespół FiboSearch','Filtering mode'=>'Tryb filtrowania','Filters that specify the product group and taxonomy that will be affected by the above mode'=>'Filtry określające grupę produktów i taksonomię, na które powyższy tryb będzie miał wpływ','Include'=>'Indeksuj tylko te produkty, które spełniają poniższe reguły','show images'=>'pokaż zdjęcia','Go to <a href="%s" target="_blank">Tools -> Site Health</a> in your WordPress. You should see issues related to REST API or Loopback request. Expand descriptions of these errors and follow the instructions. Probably you will need to contact your hosting provider to solve it.'=>'Przejdź do <a href="%s" target="_blank">Narzędzia -> Stan witryny</a> w swoim WordPressie. Powinieneś zobaczyć ostrzeżenia dotyczące działania REST API lub zapytań HTTP typu "Loopback". Rozwiń opis tych komunikatów i przeczytaj instrukcję jak je naprawić. Możliwe, że konieczny będzie kontakt z twoim hostingodawcą.','Is your website publicly available only for whitelisted IPs? <b>Add your server IP to the whitelist</b>. That’s all. This is a common mistake when access is blocked by a <code>.htaccess</code> file. Developers add a list of allowed IPs, but they forget to add the IP of the server to allow it to make HTTP requests to itself.'=>'Czy twoja strona jest dostępna tylko dla wybranych adresów IP? <b>Dodaj adres IP swojego serwera do białej listy</b>. To częsty błąd, gdy tworząc białą listę adresów IP w pliku<code>.htaccess</code>, zapomina się tam dodać także adres IP własnego serwera, aby można było wykonywać zapytania HTTP do samego siebie.','Your server can\'t send an HTTP request to itself'=>'Twój serwer nie może wysłać żądania HTTP do samego siebie','Schedule time'=>'Zaplanuj czas','FiboSearch'=>'FiboSearch','Add FiboSearch as a menu item.'=>'Dodaj FiboSearch jako element menu.','Due to the way the TranslatePress - Multilingual plugin works, we can only provide support for it in the <a href="%s" target="_blank">Pro version</a>.'=>'Wtyczka TranslatePress - Multilingual działa w specyficzny sposób, przez co niemożliwe było zintegrowaliśmy się z nią w bezpłatnej wersji FiboSearch. Udało się tego dokonać tylko w <a href="%s" target="_blank">FiboSearch Pro</a>.','FiboSearch bar'=>'Wyszukiwarka FiboSearch','FiboSearch Pro - Upgrade Now'=>'FiboSearch - kup wersję Pro','Individual tips and support from the FiboSearch team'=>'Indywidualne porady i wsparcie','Modern search engine based on an inverted index and advanced matching algorithms'=>'Nowoczesny silnik wyszukiwania oparty o listy inwersyjne i zaawansowane algorytmy.','Note: We currently only support the header type: "Header 10"'=>'Informacja: Aktualnie wspieramy tylko nagłówek typu: "Header 10"','TranslatePress'=>'TranslatePress','with simple tricks'=>'zwiększając szybkość','You are using TranslatePress with Free version of our plugin'=>'Używasz wtyczki TranslatePress z bezpłatną wersją FiboSearch','FiboSearch - AJAX Search for WooCommerce'=>'FiboSearch - AJAX Search for WooCommerce','Settings'=>'Ustawienia','Using PHP - %s'=>'Za pomocą PHP - %s','Add new rule'=>'Dodaj nową regułę','Filters'=>'Filtry','No rules'=>'Brak reguł','Server environment'=>'Środowisko serwerowe','Sold by:'=>'Sprzedawane przez:','Vendor'=>'Sprzedawca','Vendors'=>'Sprzedawcy','Extensions should looks like the picture below:'=>'Dodatki powinny wyglądać tak jak an poniższym zdjęciu:','Go to <code>WooCommerce -> Settings -> <a href="%s" target="_blank">Products Filter (tab)</a> -> Extensions (tab)</code>, uncheck <code>Searching by Text</code> extension and save changes.'=>'Przejdź do <code>WooCommerce -> Ustawienia -> <a href="%s" target="_blank">karta Products Filter</a> -> karta Extensions</code>, wyłącz dodatek <code>Searching by Text</code> i zapisz ustawienia.','Incompatible "HUSKY - Advanced searching by Text" extension from "WOOF - WooCommerce Products Filter plugin" is active'=>'Niekompatybilny dodatek "HUSKY - Advanced searching by Text" należący do wtyczki "WOOF - WooCommerce Products Filter" jest aktywny','Incompatible "Searching by Text" extension in WOOF - WooCommerce Products Filter'=>'Niekompatybilny dodatek "Searching by Text" należący do wtyczki WOOF - WooCommerce Products Filter','Go to <code>Appearance -> <a target="_blank" href="%s">Customize</a> -> Header -> Search</code> and enable <code>Predictive Search</code>'=>'Przejdź do <code>Wygląd -> <a target="_blank" href="%s">Dostosuj</a> -> Nagłówek -> Wyszukiwarka</code> i włącz <code>Predictive Search</code>','Great! Our plugin works great with this version of WordPress.'=>'Świetnie! Twoja wtyczka działa dobrze z tą wersją WordPressa.','Great! We have not detected any problems that could affect the correct functioning of our plugin.'=>'Świetnie! Nie znaleźliśmy żadnych problemów, które mogły zakłócić działanie wtyczki.','Incompatible plugins'=>'Niekompatybilne wtyczki','Incorrect "Add to cart" behaviour in WooCommerce settings'=>'Niepoprawna konfiguracja opcji "Dodaj do koszyka" w ustawieniach WooCommerce','One or more required PHP extensions are missing on your server'=>'Brakuje jednego lub więcej wymaganych rozszerzeń PHP','PHP extensions'=>'Rozszerzenia PHP','Processing asynchronous tests...'=>'Przetwarzanie asynchroniczne testów...','Search icon color'=>'Kolor ikonki wyszukiwania','Solution'=>'Rozwiązanie','Solutions:'=>'Rozwiązania:','To replace the search bar you have to enable the "Predictive Search" option in the Shopkeeper settings.'=>'W celu zastąpienia pola wyszukiwania musisz włączyć opcję "Predictive Search" w ustawieniach Shopkeeper.','Warning!'=>'Uwaga!','WordPress version'=>'Wersja WordPressa','You are using one or more incompatible plugins'=>'Używasz jednej lub kilku wtyczek, które nie są kompatybilne z FiboSearch','Your settings should look like the picture below:'=>'Twoje ustawienia powinny wyglądać tak jak na poniższym screenie:','Your site can perform loopback requests'=>'Twoja strona może wykonać żądania HTTP typu loopback','Your site could not complete a loopback request'=>'Twoja strona nie mogła wykonać żądania HTTP typu loopback','Enable AJAX add to cart buttons on archives'=>'Włącz przyciski dodawania do koszyka w technologii AJAX na stronach archiwów','Redirect to the cart page after successful addition'=>'Przekieruj do koszyka po dodaniu produktu','Hit enter to search or ESC to close'=>'Naciśnij przycisk Enter aby wyszukać lub ESC aby zamknąć','%s Theme'=>'%s Motyw','Default'=>'Domyślnie','Here is <a href="%s" target="_blank">article</a> about how to do it using Impreza child-theme.'=>'Tutaj jest <a href="%s" target="_blank">wpis</a> o tym, jak to zrobić używając motywu potomnego Impreza.','Icon on mobile, search bar on desktop'=>'Ikonka (mobilki), pole wyszukiwania (desktop)','Layout'=>'Układ','Overlay on mobile'=>'Overlay na urządzeniach mobilnych','px'=>'px','Replace the search bars'=>'Podmień pola wyszukiwania','Search icon'=>'Ikonka wyszukiwania','The search will open as an overlay on mobile'=>'Wyszukuj w trybie "overlay" na urządzeniach mobilnych','Regeneration of images started. The process will continue in the background.'=>'Odnawianie miniaturek rozpoczęte. Proces będzie kontynuowany w tle.','Regenerate WooCommerce images'=>'Odnawianie miniaturek dla WooCommerce\'a','<b>New Ultra-Fast Search Engine</b> – works very fast even with 100,000+ products '=>'<b>Nowy ultraszybki silnik wyszukiwawczy</b> – wyszukuje w mgnieniu oka nawet 100,000+ produktów.','Are there any difficulties? <b>We will do it for you!</b> We offer free of charge search bar implementation for Pro users. <a target="_blank" href="%s">Become one now!</a>'=>'Jakieś kłopoty podczas implementacji? <b>Może zrobić to za Ciebie!</b> Oferujemy bezpłatną implementację FiboSearch w Twoim motywie dla użytkowników Pro. <a target="_blank" href="%s">Wypróbuj FiboSearch Pro!</a>','continue reading'=>'kontynuuj czytanie','Individual customization of the search bar (simple CSS improvements)'=>'Indywidualne dostosowanie pola wyszukiwania (proste wskazówki CSS)','Professional and fast <b>help to embed</b> or <b>replacing</b> the search bar in your theme'=>'Profesjonalna i szybka <b>pomoc w implementacji</b> lub <b>podmianie</b> wyszukiwarki w twoim motywie.','Search by variation product SKU'=>'Szukaj w SKU wariantów produktów','Search for posts and pages'=>'Szukaj we wpisach i stronach','Search in brands (WooCommerce Brands or YITH WooCommerce Brands)'=>'Szukaj w markach (WooCommerce Brands or YITH WooCommerce Brands)','Synonyms should be separated by a comma. Each new synonyms group is entered in a new line. You can use a phrase instead of a single word. <br /> <br />Sample list:<br /> <br /><span class="dgwt-wcas-synonyms-sample">sofa, couch, davenport, divan, settee<br />big, grand, great, large, outsize</span>'=>'Synonimy powinny być oddzielone przecinkiem. Każda nowa grupa synonimów powinna być dodana od nowej linii. Można użyć fraz zamiast pojedynczych słów. <br /> <br />Przykładowa lista:<br /> <br /><span class="dgwt-wcas-synonyms-sample">sofa, kanapa, tapczan, wersalka<br />duży, wielki, ogromny, gigantyczny</span>','Update now and boost your sales. You will receive a <b>30-day satisfaction guarantee</b>.  A return on investment will come very quickly.'=>'Wypróbuj wersję Pro i zwiększ sprzedaż. Gwarantujemy <b>30-dniowy zwrot pieniędzy</b>. Inwestycja w FiboSearch zwróci się błyskawicznie.','Using a shortcode - %s'=>'Za pomocą shortcode\'a - %s','Add to cart'=>'Dodaj do koszyka','Search in tags'=>'Szukaj w tagach','Synonyms'=>'Synonimy','The most popular WooCommerce product search. Gives your users a well-designed advanced AJAX search bar with live search suggestions.'=>'Najpopularniejsza wtyczka do szukania produktów w WooCommerce. Pozwala użytkownikom twojego sklepu używać dobrze zaprojektowanej wyszukiwarki AJAX, która wyświetla wyniki w czasie rzeczywistym.','As a menu item - go to the %s and add the menu item “FiboSearch bar”. Done!'=>'Jako element menu - idź do %s i dodaj pozycję "Wyszukiwarka FiboSearch". Gotowe!','daily'=>'dzienny','Enable Scheduler'=>'Włącz harmonogram','FiboSearch bar will be displayed here.'=>'Pole wyszukiwania FiboSearch będzie tutaj wyswietlone.','How to add?'=>'Jak dodać?','In most cases, you don\'t need to use the scheduler because the search index updates when you edit products. If you use import tools or custom code to refresh prices or bulk add/edit products, the indexing scheduler will be helpful.'=>'W większości przypadków nie trzeba używać harmonogramu budowania indeksu, ponieważ indeks wyszukiwawczy jest i tak aktualizowany w locie, podczas edytowania produktów. Jeżeli używasz narzędzi do importu lub własnych skryptów do odświeżania cen, lub innych operacji zbiorowych na produktach, wtedy harmonogram budowy indeksu może się przydać.','Interval'=>'Interwał','Menu Screen'=>'widoku menu','Scheduling indexing'=>'Harmonogram indeksowania','weekly'=>'tygodniowy','Add to menu'=>'Dodaj do menu','adminNo results label'=>'Brak wyników [tekst]','Alternative ways to embed a search bar'=>'Inne sposoby na wyświetlanie pola wyszukiwania','Autocomplete'=>'Autouzupełnienie','Brands'=>'Marki','child theme of <b>%s</b>'=>' motywu potomnego <b>%s</b>','How to add search bar in your theme?'=>'Jak dodać pole wyszukiwania w twoim motywie?','Increases sales conversions.'=>'Zwiększ konwersję sprzedaży.','Indexer'=>'Indeks','Limit'=>'Limit','Lorem <strong>ipsum</strong> dolor sit amet, consectetur adipiscing elit. Quisque gravida lacus nec diam porttitor pharetra. Nulla facilisi. Proin pharetra imperdiet neque, non varius.'=>'Lorem <strong>ipsum</strong> dolor sit amet, consectetur adipiscing elit. Quisque gravida lacus nec diam porttitor pharetra. Nulla facilisi. Proin pharetra imperdiet neque, non varius.','Min characters to show autocomplete'=>'Po ilu literach pokazać podpowiedzi?','More results label'=>'Wiecej wyników [tekst]','Non-products in autocomplete'=>'Inne rodzaje podpowiedzi','Preview'=>'Podgląd','Products'=>'Produkty','Sample brand <strong>name</strong>'=>'Przykładowa <strong>nazwa</strong> marki','Sample category <strong>name</strong>'=>'Przykładowa <strong>nazwa</strong> kategorii.','Sample product <strong>name</strong>'=>'Przykładowa <strong>nazwa</strong> produktu','Sample product name'=>'Przykładowa nazwa produktu','Sample tag <strong>name</strong>'=>'Przykładowa<strong>nazwa</strong> tagu','Search bar'=>'Pole wyszukiwania','Search config'=>'Wyszukiwanie','Search in categories'=>'Szukaj w kategoriach','See all products...'=>'Zobacz wszystkie produkty','Show advanced settings'=>'Pokaż zaawansowane opcje','Show brands'=>'Pokaż marki','Show categories'=>'Pokaż kategorie','Show Details Panel'=>'Pokaż panel ze szczegółami','Show pages'=>'Pokaż strony','Show posts'=>'Pokaż wpisy','Show tags'=>'Pokaż tagi','Starting'=>'Jak zacząć?','Suggestions colors'=>'Kolory podpowiedzi','We support this theme so you can easily replace all default search bars.'=>'Obsługujemy ten motyw, więc możesz automatycznie podmienić domyślą wyszukiwarkę produktów. ','Featured'=>'Wyróżnione','Sale'=>'Promocja','SKU'=>'SKU','Tags'=>'Tagi','Categories'=>'Kategorie','https://fibosearch.com?utm_source=wp-admin&utm_medium=referral&utm_campaign=author_uri&utm_gen=utmdc'=>'https://fibosearch.com?utm_source=wp-admin&utm_medium=referral&utm_campaign=author_uri&utm_gen=utmdc','Sample %s <strong>name</strong>'=>'Przykładowa <strong>nazwa</strong> %s','As a widget - go to the %s and choose “FiboSearch bar”'=>'Jako widget - idź do %s i wybierz "Wyszukiwarka FiboSearch"','Based on the plugin %s'=>'na podstawie wtyczki %s','Brand'=>'Marka','Products search scope'=>'Zakres wyszukiwania produktów','Search in brands'=>'Szukaj w markach','Search in custom fields'=>'Szukaj we własnych polach','See a comparison of all free and premium features!'=>'zobacz różnice między wersją Free oraz Pro!','Showcase'=>'Przykłady','There are %s easy ways to display the search bar in your theme'=>'Istnieje %s prostych sposobów wyświetlania paska wyszukiwania w Twoim motywie','Searching in variable products SKU is available only in <a target="_blank" href="%s">the pro version</a>.'=>'Szukanie w SKU wariantów dostępne jest tylko w <a href="%s">wersji Pro</a>.','-- Disabled'=>'-- Wyłączone','And more...'=>'I więcej...','and more...'=>'i dużo więcej...','Contact'=>'Kontakt','Fuzziness'=>'Rozmycie','Fuzzy matching'=>'Dopasowanie rozmyte','Fuzzy search'=>'Dopasowanie rozmyte','Hard'=>'Silne','If users can’t find the product they’re searching for, they can’t buy it. Help your customers to find the right products even <span>10× faster</span>.'=>'Klienci nie kupią produktów, których nie będą mogli znaleźć. Pomóż im znaleźć właściwe produkty nawet <span>10 razy szybciej</span>.','in categories fe. in Books > Crime storiesin'=>'w','Increase sales'=>'Popraw sprzedaż','Index status'=>'Status indeksu','Normal'=>'Średnie','Pro features'=>'Funkcjonalności Pro','Required PHP extension: %s'=>'Wymagane rozszerzenia PHP: %s','Search in attributes'=>'Szukaj w atrybutach','Search in attributes and variation products SKUs (option)'=>'Szukaj w atrybutach oraz w SKU wariantów produktów (opcja)','Search in description'=>'Szukaj w opisie','Search in short description'=>'Szukaj w krótkim opisie','Search in SKU'=>'Szukaj w SKU','searching also in variable products SKU'=>'Przeszukuje także SKU wariantów','Show details'=>'Pokaż szczegóły','Soft'=>'Słabe','Speed up search!'=>'Przyspiesz wyszukiwanie!','Speed up search! (even 10× faster) - users love it!'=>'Przyspieszenie wyszukiwania! (nawet 10 razy szybciej)','The search index does not exist yet. Build it now.'=>'Indeks wyszukiwawczy jeszcze nie istnieje. Zbuduj go teraz.','Update now and increase your sales. You will receive a 30-day satisfaction guarantee.  A return on investment will come very quickly.'=>'Wypróbuj wersję Pro i zwiększ sprzedaż. Gwarantujemy <b>30-dniowy zwrot pieniędzy</b>. Inwestycja w FiboSearch zwróci się błyskawicznie.','Upgrade Now'=>'Kup wersję Pro','Upgrade Now!'=>'Kup wersję Pro!','Build index'=>'Zbuduj indeks','Max form width'=>'Maksymalna szerokość pola wyszukiwania','Pro'=>'Pro','To set 100% width leave blank'=>'Zostaw puste aby uzyskać 100% szer.','Troubleshooting'=>'Rozwiązywanie problemów','No thanks'=>'Zamknij','Review %s'=>'Oceń teraz','Exclude “out of stock” products'=>'Wyklucz produkty o zerowym stanie magazynowym','No results'=>'Brak wyników','Show SKU'=>'Pokaż SKU','AJAX (live) search form for WooCommerce'=>'Wyszukiwarka do WooCommerce z autouzupełnianiem od FiboSearch.','Basic'=>'Podstawowe','Border color'=>'Kolor obramowania','Highlight color'=>'Kolor podświetlenia','maximum number of suggestions'=>'maksymalna liczba podpowiedzi','Minimum characters'=>'Minimalna liczba znaków','Preloader'=>'Preloader','Products search'=>'Wyszukiwarka produktów','Search'=>'Szukaj','Search for products...'=>'Szukaj produktów','Search input background'=>'Tło pola do wpisania frazy','Search input border'=>'Obramowanie inputa','Search input placeholder'=>'Placeholder dla pola wyszukiwania','Search input text'=>'Tekst ','Show preloader'=>'Pokaż preloader','Show price'=>'Pokaż cenę','Show product description'=>'Pokaż opis produktu','Show product image'=>'Pokaż zdjęcie produktu','Show submit button'=>'Pokaż przycisk "Szukaj"','Style'=>'Styl','Suggestion background'=>'Tło podpowiedzi','Suggestion selected'=>'Tło zaznaczonej podpowiedzi','Text color'=>'Kolor tekstu','The Details Panel is an additional container for extended information. The details change dynamically when the cursor hovers over one of the suggestions.'=>'Panel ze szczegółami jest dodatkowym miejscem wyświetlających szczegóły dla każdej podpowiedzi. Pojawia się po najechaniu kursorem na podpowiedź.','Title'=>'Tytuł','To display the magnifier icon leave this field empty.'=>'Aby wyświetlić ikonkę lupy, pozostaw to pole puste.','Upload preloader image'=>'Załaduj zdjęcie na preloader','Widgets Screen'=>'widoku widgetów','Tag'=>'Tag','Category'=>'Kategoria','Choose File'=>'Wybierz plik']];